/**
 * Shop files. Each media entry offers a cover and the formats in `formats` (default epub, pdf, md).
 * A file the entry supplies (`cover`, `files.<format>`, in public/assets/) is used as-is. Every other
 * one is generated by `pnpm media` (scripts/media.ts) into `media-files/<slug>/`, with a
 * `manifest.json` recording the hash of its inputs. The build never runs pandoc or typst: it reads
 * the plan from here and copies files. Generated text comes from the transmission, or from a whole
 * book (intro, contents, every essay in `essays` order), one file per format.
 */
import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { stringify as yamlStringify } from 'yaml'
import { assetRefs } from './assets.ts'
import { collectionIntro } from './collections.ts'
import { WORKSPACE } from './config.ts'
import type { Entry, OuterMind } from './load.ts'
import { siteBase } from './links.ts'
import { resolveWikilinks } from './markdown.ts'

// Paths from the workspace root, so they hold inside Astro's bundle too.
const HERE = join(WORKSPACE, 'packages/content')
const TEMPLATES = join(HERE, 'templates')
const TOKENS = join(WORKSPACE, 'packages/ui/tokens.css')
const FONTS = join(WORKSPACE, 'packages/ui/fonts/mediashop')
/** Where `pnpm media` writes generated files. Committed to git, so any build can copy them. */
export const MEDIA_FILES = process.env.OM_MEDIA_FILES || join(WORKSPACE, 'media-files')

/** Default edition language: the content model has no language field yet. */
export const EDITION_LANGUAGE = 'en'

export type Format = 'epub' | 'pdf' | 'md'
export const FORMAT_TYPES: Record<Format, string> = {
  epub: 'application/epub+zip',
  pdf: 'application/pdf',
  md: 'text/markdown',
}

/** `--ed-*` values from packages/ui/tokens.css. */
export function editionTokens(): Record<string, string> {
  const css = readFileSync(TOKENS, 'utf8')
  const out: Record<string, string> = {}
  for (const m of css.matchAll(/--(ed-[a-z0-9-]+)\s*:\s*([^;]+);/g)) out[m[1]] = m[2].trim().replace(/^'|'$/g, '')
  return out
}

const sha = (s: string | Buffer) => createHash('sha256').update(s).digest('hex')

function dirHash(dir: string): string {
  if (!existsSync(dir)) return ''
  return sha(
    readdirSync(dir)
      .sort()
      .map((f) => `${f}:${sha(readFileSync(join(dir, f)))}`)
      .join('|'),
  )
}

let toolVersions: string | undefined
function tools(): string {
  toolVersions ??= [
    execFileSync('pandoc', ['--version']).toString().split('\n')[0],
    execFileSync('typst', ['--version']).toString().trim(),
  ].join(' | ')
  return toolVersions
}

/** The transmission or collection an edition is made from. */
export function editionSource(om: OuterMind, m: Entry<'media'>) {
  const s = m.data.edition_of ? om.bySlug.get(m.data.edition_of) : undefined
  return s && (s.type === 'transmission' || s.type === 'collection')
    ? (s as Entry<'transmission'> | Entry<'collection'>)
    : undefined
}

function pieces(om: OuterMind, src: Entry<'transmission'> | Entry<'collection'>): Entry<'transmission'>[] {
  if (src.type !== 'collection') return []
  return (src as Entry<'collection'>).data.essays
    .map((s) => om.bySlug.get(s))
    .filter((e): e is Entry<'transmission'> => e?.type === 'transmission')
}

/** Shift every markdown heading down a level (outside code), so book chapters are the top level. */
function demote(md: string): string {
  return md
    .split(/(```[\s\S]*?```)/g)
    .map((part, i) => (i % 2 ? part : part.replace(/^(#{1,5})(\s)/gm, '#$1$2')))
    .join('')
}

/**
 * Markdown prepared for pandoc: links resolved to absolute URLs, local images kept as `assets/…`
 * (found through --resource-path), remote images turned into links so the build never fetches them.
 */
function prepare(om: OuterMind, md: string): string {
  const base = siteBase(om, 'mediashop')
  return resolveWikilinks(md, { om, site: 'mediashop' })
    .replace(/\]\(<(\/[^>]*)>\)/g, (_m, p: string) => `](<${base}${p}>)`)
    .replace(/!\[([^\]]*)\]\((https?:[^)\s]+)\)/g, (_m, alt: string, url: string) => `[${alt || 'Image'}](${url})`)
}

function authors(m: Entry<'media'>, src: Entry, om: OuterMind): string[] {
  const a = m.data.author ?? (src.data as { author?: string[] }).author
  if (a?.length) return a
  const hub = om.site?.data.sites.find((s) => s.name.toLowerCase() === 'hub')
  return [hub?.title ?? 'The Open Machine']
}

/** The one markdown document every format is made from. */
function sourceMarkdown(om: OuterMind, m: Entry<'media'>, src: Entry<'transmission'> | Entry<'collection'>) {
  const meta = {
    title: m.data.title,
    ...(m.data.subtitle ? { subtitle: m.data.subtitle } : {}),
    author: authors(m, src, om),
    date: src.data.date,
    lang: EDITION_LANGUAGE,
    ...(m.data.licence || om.site?.data.licence ? { rights: m.data.licence ?? om.site?.data.licence } : {}),
    identifier: `urn:om:${m.slug}`,
  }
  let body: string
  if (src.type === 'collection') {
    const list = pieces(om, src)
    const intro = prepare(om, collectionIntro(src as Entry<'collection'>)).trim()
    const toc = ['# Contents {.unnumbered}', '', ...list.map((p, i) => `${i + 1}. [${p.data.title}](#${p.slug})`)].join('\n')
    const chapters = list.map((p) => `# ${p.data.title} {#${p.slug}}\n\n${demote(prepare(om, p.body)).trim()}`)
    body = [intro, toc, ...chapters].filter(Boolean).join('\n\n')
  } else {
    body = prepare(om, src.body).trim()
  }
  return { meta, md: `---\n${yamlStringify(meta)}---\n\n${body}\n` }
}

function run(cmd: string, args: string[], env: Record<string, string>) {
  try {
    execFileSync(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...env } })
  } catch (e) {
    const err = e as { stderr?: Buffer; message: string }
    throw new Error(`${cmd} failed: ${err.stderr?.toString().trim() || err.message}`)
  }
}

/** @font-face rules for the embedded fonts (pandoc puts them in the EPUB's fonts/ folder). */
function fontFaces(): string {
  const families: Record<string, string> = { 'instrument-sans': 'Instrument Sans', newsreader: 'Newsreader' }
  return readdirSync(FONTS)
    .filter((f) => f.endsWith('.ttf'))
    .map((f) => {
      const m = f.match(/^(.*?)-latin-(\d+)-(normal|italic)\.ttf$/)
      if (!m || !families[m[1]]) return ''
      return `@font-face { font-family: '${families[m[1]]}'; font-weight: ${m[2]}; font-style: ${m[3]}; src: url('../fonts/${f}'); }`
    })
    .filter(Boolean)
    .join('\n')
}

function epubCss(t: Record<string, string>): string {
  const css = readFileSync(join(TEMPLATES, 'epub.css'), 'utf8').replace(/var\(--(ed-[a-z0-9-]+)\)/g, (_m, k) => t[k] ?? '')
  return `${fontFaces()}\n${css}`
}

function typstHeader(t: Record<string, string>): string {
  return readFileSync(join(TEMPLATES, 'edition-header.typ'), 'utf8').replace(/\{\{(ed-[a-z0-9-]+)\}\}/g, (_m, k) => t[k] ?? '')
}

async function makeCover(dir: string, m: Entry<'media'>, who: string[], t: Record<string, string>, om: OuterMind, epoch: string) {
  const svg = join(dir, 'cover.svg')
  const kicker = om.site?.data.sites.find((s) => s.name.toLowerCase() === 'hub')?.title ?? 'The Open Machine'
  const inputs: Record<string, string> = {
    title: m.data.title,
    subtitle: m.data.subtitle ?? '',
    author: who.join(', '),
    kicker,
    bg: t['ed-cover-bg'],
    fg: t['ed-cover-fg'],
    muted: t['ed-cover-muted'],
    rule: t['ed-cover-rule'],
    heading: t['ed-font-heading'],
    body: t['ed-font-body'],
  }
  run(
    'typst',
    [
      'compile',
      '--format', 'svg',
      '--font-path', FONTS,
      '--ignore-system-fonts',
      ...Object.entries(inputs).flatMap(([k, v]) => ['--input', `${k}=${v}`]),
      join(TEMPLATES, 'cover.typ'),
      svg,
    ],
    { SOURCE_DATE_EPOCH: epoch },
  )
  const sharp = (await import('sharp')).default
  // The cover page is 288 × 432 pt. librsvg scales pt units by the density twice, so render at
  // a density that lands just above 1600 px wide, then resize to exactly 1600 × 2400 px.
  await sharp(readFileSync(svg), { density: 170 })
    .resize(1600, 2400, { fit: 'fill' })
    .png({ compressionLevel: 9 })
    .toFile(join(dir, 'cover.png'))
}

/** A cover or a format. */
export type Piece = Format | 'cover'
export const pieceFile = (slug: string, p: Piece) => (p === 'cover' ? 'cover.png' : `${slug}.${p}`)
const LABEL: Record<Piece, string> = { cover: 'cover', epub: 'EPUB', pdf: 'PDF', md: 'Markdown' }

export interface ShopPlan {
  media: Entry<'media'>
  source?: Entry<'transmission'> | Entry<'collection'>
  formats: Format[]
  /** Supplied files, as refs relative to public/ (e.g. `assets/x.pdf`). */
  supplied: Partial<Record<Piece, string>>
  /** What `pnpm media` must generate: everything offered that isn't supplied. */
  generate: Piece[]
  /** media-files/<slug> */
  dir: string
}

export function shopPlan(om: OuterMind, m: Entry<'media'>): ShopPlan {
  const formats = m.data.formats as Format[]
  const supplied: Partial<Record<Piece, string>> = {}
  if (m.data.cover) supplied.cover = m.data.cover
  for (const f of formats) {
    const ref = (m.data.files as Partial<Record<Format, string>> | undefined)?.[f]
    if (ref) supplied[f] = ref
  }
  const generate: Piece[] = [...(supplied.cover ? [] : (['cover'] as Piece[])), ...formats.filter((f) => !supplied[f])]
  return { media: m, source: editionSource(om, m), formats, supplied, generate, dir: join(MEDIA_FILES, m.slug) }
}

/** Every input that can change a generated file, hashed. Tool versions are recorded, not hashed, so the build needs no tools. */
function inputsKey(om: OuterMind, plan: ShopPlan): string {
  const src = plan.source!
  const entries: Entry[] = [plan.media, src, ...pieces(om, src)]
  const assets = [...new Set(entries.flatMap(assetRefs))].sort().map((r) => {
    const f = join(om.publicDir, r)
    return `${r}:${existsSync(f) ? sha(readFileSync(f)) : 'missing'}`
  })
  return sha(
    JSON.stringify({
      entries: entries.map((e) => [e.slug, e.data, e.body]),
      assets,
      generate: plan.generate,
      base: siteBase(om, 'mediashop'),
      templates: dirHash(TEMPLATES),
      tokens: sha(readFileSync(TOKENS)),
      fonts: dirHash(FONTS),
      code: sha(readFileSync(join(HERE, 'editions.ts'))),
    }),
  ).slice(0, 16)
}

interface Manifest {
  key: string
  generated: Piece[]
  tools?: string
}
function readManifest(dir: string): Manifest | undefined {
  try {
    return JSON.parse(readFileSync(join(dir, 'manifest.json'), 'utf8'))
  } catch {
    return undefined
  }
}

export type PieceState = 'supplied' | 'fresh' | 'stale' | 'missing'
export interface ShopFile {
  piece: Piece
  label: string
  state: PieceState
  /** Absolute path of the file (supplied: in public/; generated: in media-files/). */
  path: string
  /** URL path on the shop. A supplied cover keeps its asset URL; everything else is /media/<slug>/<file>. */
  href: string
}

/** Each offered piece (cover first, then formats), where it comes from, and whether it's ready. */
export function shopFiles(om: OuterMind, m: Entry<'media'>): { plan: ShopPlan; files: ShopFile[] } {
  const plan = shopPlan(om, m)
  const key = plan.source ? inputsKey(om, plan) : undefined
  const manifest = readManifest(plan.dir)
  const files: ShopFile[] = (['cover', ...plan.formats] as Piece[]).map((piece) => {
    const ref = plan.supplied[piece]
    if (ref) {
      return {
        piece,
        label: LABEL[piece],
        state: 'supplied',
        path: join(om.publicDir, ref),
        href: piece === 'cover' ? `/${ref}` : `/media/${m.slug}/${pieceFile(m.slug, piece)}`,
      }
    }
    const path = join(plan.dir, pieceFile(m.slug, piece))
    const state: PieceState = !existsSync(path)
      ? 'missing'
      : manifest?.key === key && manifest.generated.includes(piece)
        ? 'fresh'
        : 'stale'
    return { piece, label: LABEL[piece], state, path, href: `/media/${m.slug}/${pieceFile(m.slug, piece)}` }
  })
  return { plan, files }
}

export type MediaResult = { status: 'generated' | 'up to date' | 'nothing to generate'; generated: Piece[]; removed: Piece[] }

/** `pnpm media` for one entry: generates what's missing or stale, removes generated files no longer needed. */
export async function generateMedia(om: OuterMind, m: Entry<'media'>, opts: { force?: boolean } = {}): Promise<MediaResult> {
  const { plan, files } = shopFiles(om, m)
  const src = plan.source
  if (!src) throw new Error(`edition_of "${m.data.edition_of}" is not a transmission or collection`)
  const before = existsSync(plan.dir) ? readdirSync(plan.dir).filter((f) => f !== 'manifest.json') : []
  const wanted = new Set(plan.generate.map((p) => pieceFile(m.slug, p)))
  const removable = (): Piece[] =>
    before
      .filter((f) => !wanted.has(f))
      .map((f) => (f === 'cover.png' ? 'cover' : (f.split('.').pop() as Piece)))

  if (!plan.generate.length) {
    const removed = removable()
    rmSync(plan.dir, { recursive: true, force: true })
    return { status: 'nothing to generate', generated: [], removed }
  }
  const ready = files.filter((f) => f.state !== 'supplied').every((f) => f.state === 'fresh')
  if (ready && !opts.force && before.every((f) => wanted.has(f))) return { status: 'up to date', generated: [], removed: [] }

  const tmp = `${plan.dir}.tmp`
  rmSync(tmp, { recursive: true, force: true })
  mkdirSync(tmp, { recursive: true })
  try {
    return await generateInto(om, m, plan, tmp)
  } finally {
    rmSync(tmp, { recursive: true, force: true })
  }
}

async function generateInto(om: OuterMind, m: Entry<'media'>, plan: ShopPlan, tmp: string): Promise<MediaResult> {
  const src = plan.source!
  const before = existsSync(plan.dir) ? readdirSync(plan.dir).filter((f) => f !== 'manifest.json') : []
  const wanted = new Set(plan.generate.map((p) => pieceFile(m.slug, p)))
  const t = editionTokens()
  const { meta, md } = sourceMarkdown(om, m, src)
  const epoch = String(Date.parse(`${src.data.date}T00:00:00Z`) / 1000)
  const env = { SOURCE_DATE_EPOCH: epoch }
  const work = join(tmp, '.work')
  mkdirSync(work)
  const srcFile = join(work, 'source.md')
  writeFileSync(srcFile, md)
  const need = new Set(plan.generate)

  let coverPath = plan.supplied.cover ? join(om.publicDir, plan.supplied.cover) : undefined
  if (need.has('cover')) {
    await makeCover(work, m, meta.author, t, om, epoch)
    copyFileSync(join(work, 'cover.png'), join(tmp, 'cover.png'))
    coverPath = join(tmp, 'cover.png')
  }
  const common = ['--from', 'markdown-citations', '--resource-path', `${om.publicDir}:${work}`, '--standalone', '--lua-filter', join(TEMPLATES, 'anchors.lua')]

  if (need.has('md')) {
    // The Markdown edition: frontmatter (title, author, date, licence) and the text, images pointing at the shop.
    const base = siteBase(om, 'mediashop')
    writeFileSync(join(tmp, `${m.slug}.md`), md.replace(/\]\(assets\//g, `](${base}/assets/`))
  }
  if (need.has('epub')) {
    writeFileSync(join(work, 'epub.css'), epubCss(t))
    const fonts = readdirSync(FONTS).filter((f) => f.endsWith('.ttf')).map((f) => `--epub-embed-font=${join(FONTS, f)}`)
    run('pandoc', [srcFile, ...common, '--to', 'epub3', '--css', join(work, 'epub.css'), ...(coverPath ? ['--epub-cover-image', coverPath] : []), ...fonts, '--output', join(tmp, `${m.slug}.epub`)], env)
  }
  if (need.has('pdf')) {
    writeFileSync(join(work, 'header.typ'), typstHeader(t))
    run(
      'pandoc',
      [
        srcFile,
        ...common,
        '--pdf-engine', 'typst',
        `--pdf-engine-opt=--font-path=${FONTS}`,
        '--pdf-engine-opt=--ignore-system-fonts',
        '--include-in-header', join(work, 'header.typ'),
        '-V', `mainfont=${t['ed-font-body']}`,
        '-V', `fontsize=${t['ed-size-body']}`,
        '-V', 'papersize=a5',
        '--output', join(tmp, `${m.slug}.pdf`),
      ],
      env,
    )
  }
  rmSync(work, { recursive: true, force: true })
  const manifest: Manifest = { key: inputsKey(om, plan), generated: plan.generate, tools: tools() }
  writeFileSync(join(tmp, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n')
  const removed = before
    .filter((f) => !wanted.has(f))
    .map((f) => (f === 'cover.png' ? 'cover' : (f.split('.').pop() as Piece)))
  rmSync(plan.dir, { recursive: true, force: true })
  renameSync(tmp, plan.dir)
  return { status: 'generated', generated: plan.generate, removed }
}

/** Removes media-files/<slug> folders whose media entry no longer exists. Returns their names. */
export function pruneMediaFiles(om: OuterMind): string[] {
  if (!existsSync(MEDIA_FILES)) return []
  const slugs = new Set(om.entries.filter((e) => e.type === 'media').map((e) => e.slug))
  const gone = readdirSync(MEDIA_FILES).filter((d) => !d.startsWith('.') && !d.endsWith('.tmp') && statSync(join(MEDIA_FILES, d)).isDirectory() && !slugs.has(d))
  for (const d of gone) rmSync(join(MEDIA_FILES, d), { recursive: true, force: true })
  return gone
}

/** Copies an item's offered files (supplied or generated, whichever exists) to `<outDir>/media/<slug>/`. A supplied cover ships with the assets. */
export function copyShopFiles(om: OuterMind, m: Entry<'media'>, outDir: string): number {
  const dest = join(outDir, 'media', m.slug)
  let n = 0
  for (const f of shopFiles(om, m).files) {
    if (f.piece === 'cover' && f.state === 'supplied') continue
    if (f.state === 'missing' || !existsSync(f.path)) continue
    mkdirSync(dest, { recursive: true })
    copyFileSync(f.path, join(dest, pieceFile(m.slug, f.piece)))
    n++
  }
  return n
}

/** Is a command on PATH? */
export function hasTool(cmd: string): boolean {
  try {
    execFileSync(cmd, ['--version'], { stdio: 'ignore' })
    return true
  } catch {
    return false
  }
}
